// UpdateNewValues updates the mutable fields using the new values that were set on create except the ID field.
// Using this option is equivalent to using:
//
//	client.Operation.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(operation.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *OperationUpsertOne) UpdateNewValues() *OperationUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		if _, exists := u.create.mutation.ID(); exists {
			s.SetIgnore(operation.FieldID)
		}
		if _, exists := u.create.mutation.CreatedAt(); exists {
			s.SetIgnore(operation.FieldCreatedAt)
		}
		if _, exists := u.create.mutation.Kind(); exists {
			s.SetIgnore(operation.FieldKind)
		}
		if _, exists := u.create.mutation.IdempotencyKey(); exists {
			s.SetIgnore(operation.FieldIdempotencyKey)
		}
		if _, exists := u.create.mutation.RequestHash(); exists {
			s.SetIgnore(operation.FieldRequestHash)
		}
		if _, exists := u.create.mutation.RequestPayload(); exists {
			s.SetIgnore(operation.FieldRequestPayload)
		}
		if _, exists := u.create.mutation.ActorUserID(); exists {
			s.SetIgnore(operation.FieldActorUserID)
		}
		if _, exists := u.create.mutation.ActorSessionID(); exists {
			s.SetIgnore(operation.FieldActorSessionID)
		}
		if _, exists := u.create.mutation.AuditID(); exists {
			s.SetIgnore(operation.FieldAuditID)
		}
		if _, exists := u.create.mutation.Reason(); exists {
			s.SetIgnore(operation.FieldReason)
		}
		if _, exists := u.create.mutation.CorrelationID(); exists {
			s.SetIgnore(operation.FieldCorrelationID)
		}
		if _, exists := u.create.mutation.TotalCount(); exists {
			s.SetIgnore(operation.FieldTotalCount)
		}
		if _, exists := u.create.mutation.BatchSize(); exists {
			s.SetIgnore(operation.FieldBatchSize)
		}
		if _, exists := u.create.mutation.NotBefore(); exists {
			s.SetIgnore(operation.FieldNotBefore)
		}
	}))
	return u
}

